INSERT INTO `blocks` VALUES (1,'arici-bali','card','Arıcı Balı',10,1,'{\"icon\":\"dipper\",\"title\":\"Arıcı Balı\",\"text\":\"Kovanımızdan sofranıza, süzülmüş ve katkısız bal.\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"/#urunler\"}}','2026-10-10 10:46:35'),(2,'ari-bahcesi','card','Arı Bahçesi',20,1,'{\"icon\":\"hive\",\"title\":\"Arı Bahçesi\",\"text\":\"Çiçeğin en bereketli olduğu yaylalarda gezgin arıcılık.\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"/#hizmetler\"}}','2026-10-10 10:46:35'),(3,'ari-urunleri','card','Arı Ürünleri',30,1,'{\"icon\":\"jar\",\"title\":\"Arı Ürünleri\",\"text\":\"Polen, arı sütü ve bal sabunu ile doğanın saf hali.\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"/#urunler\"}}','2026-10-10 10:46:35'),(4,'bali-dogru-anlatmak','post','Arıcılığın ötesinde: balı doğru anlatmak',10,1,'{\"title\":\"Arıcılığın ötesinde: balı doğru anlatmak\",\"date\":\"28 Eylül 2026\",\"comments\":\"Yorum yok\",\"excerpt\":\"İyi bal, yalnızca tat değildir. Çiçek, mevsim ve kovan aynı etikette buluştuğunda müşteri ne aldığını bilir.\",\"image\":\"assets/images/blog-1.jpg\",\"image_alt\":\"Yakın plan petek\",\"embed_keys\":[\"arici-bali\",\"ari-bahcesi\",\"ari-urunleri\"],\"body\":[\"Kavanozun üzerindeki kısa cümle, balın bütün hikâyesini taşımalı. Çiçek kaynağı, hasat ayı ve kovan belli değilse müşteri yalnızca bir tat satın alır; kaynağını sorduğunda ise cevap kalmaz.\",\"Tuana Arıcılık her partiyi ayrı not eder. Süzüm tarihi, çiçek dönemi ve kovan aynı kayıttadır. Böylece “bu bal nereden?” sorusu ezbere bir sloganla değil, izlenebilir bir cevapla kapanır.\",\"Anlatmak, balı süslemek değildir. Isı görmeden süzülen, katkısız ve mevsimin kıvamını koruyan ürünü olduğu gibi tarif etmek yeter.\"],\"author\":\"Tuana Arıcılık\",\"time\":\"09:40\",\"category\":\"Arıcılık\",\"category_key\":\"aricilik\",\"tags\":[\"Bal\",\"Hasat\",\"Etiket\"],\"figure\":{\"image\":\"assets/images/promo.jpg\",\"image_alt\":\"Petekten kaba damlayan bal\",\"caption\":\"Petekten süzülen bal, ısıtılmadan dinlendirilir.\"}}','2026-10-10 10:53:20'),(5,'kendi-ari-bahcesi','post','Kendi arı bahçenizi nasıl kurarsınız',20,1,'{\"title\":\"Kendi arı bahçenizi nasıl kurarsınız\",\"date\":\"12 Eylül 2026\",\"comments\":\"Yorum yok\",\"excerpt\":\"İlk kovan için rüzgâr, su ve çiçek takvimi yeter. Kalabalık söz vermeden, sahada işe yarayan bir başlangıç.\",\"image\":\"assets/images/blog-2.jpg\",\"image_alt\":\"Çiçek üzerindeki arı\",\"embed_keys\":[\"ari-bahcesi\"],\"body\":[\"İlk kovanı koymadan önce yer seçilir. Sabah güneşi alan, öğleden sonra gölgelenebilen ve sert rüzgâra kapalı bir nokta, arının uçuş hattını rahatlatır. Su kaynağı yakın, ama kovanın tam ağzında olmamalıdır.\",\"Çiçek takvimi bahçenin asıl planıdır. İlkbaharda meyve, yazın çayır, sona doğru ise geç çiçekler birbirini izlemezse koloni aç kalır. Boş geçen haftaları fark etmek, yeni kovan almaktan önce gelir.\",\"Tek kovanla başlamak yeter. Kalabalık bir arılık, tecrübe yokken hem arıyı hem arıcıyı yorar. İlk sezonun işi bal vaadi değil, koloniyi kışa sağlıklı bırakmaktır.\"],\"author\":\"Tuana Arıcılık\",\"time\":\"11:15\",\"category\":\"Bahçe\",\"category_key\":\"bahce\",\"tags\":[\"Bahçe\",\"Kovan\",\"Başlangıç\"],\"figure\":{\"image\":\"assets/images/service-keeping.jpg\",\"image_alt\":\"Arıcı kovan başında çerçeve kontrol ediyor\",\"caption\":\"İlk kovan, rüzgârdan korunmuş bir hatta durur.\"}}','2026-10-10 10:53:20'),(6,'arici-olmayi-ogrenmek','post','Arıcı olmayı öğrenmek',30,1,'{\"title\":\"Arıcı olmayı öğrenmek\",\"date\":\"2 Eylül 2026\",\"comments\":\"Yorum yok\",\"excerpt\":\"Koruyucu kıyafet ve çerçeve kontrolü, arıcılığın ilk günündeki iki temel alışkanlıktır. Gerisi koloniyi izleyerek gelir.\",\"image\":\"assets/images/blog-3.jpg\",\"image_alt\":\"Kovan başında çalışan arıcı\",\"embed_keys\":[],\"body\":[\"İlk günün iki alışkanlığı vardır: maskeyi acele çıkarmamak ve çerçeveyi dik tutmak. Petek kırılırsa hem bal akar hem de koloni huzursuz olur. Yavaş el, arıcılığın ilk ustalığıdır.\",\"Kontrol sık değil, düzenli yapılır. Yavru alanı, bal kemeri ve ana arının varlığı aynı bakışta aranır. Her açılış bir nottur: tarih, hava ve görülen değişiklik.\",\"Gerisi koloniyi izleyerek gelir. Kitaptaki liste, kovanın o günkü haline yenilir. Öğrenmek, her ziyarette bir şeyi daha sakin görmektir.\"],\"author\":\"Tuana Arıcılık\",\"time\":\"14:05\",\"category\":\"Arıcılık\",\"category_key\":\"aricilik\",\"tags\":[\"Arıcılık\",\"Kovan\",\"Öğrenme\"],\"figure\":{\"image\":\"assets/images/why.jpg\",\"image_alt\":\"Arıcı bal dolu çerçeveyi tutuyor\",\"caption\":\"Çerçeve dik tutulur; petek kırılmadan kontrol edilir.\"}}','2026-10-10 10:53:20'),(7,'koloni-bakimi','post','Güçlü bir bal akışı için koloni bakımı',40,1,'{\"title\":\"Güçlü bir bal akışı için koloni bakımı\",\"date\":\"18 Ağustos 2026\",\"comments\":\"Yorum yok\",\"excerpt\":\"Kraliçe, yavru alanı ve boş petek dengesi bozulunca akış da bozulur. Hasattan önce koloninin ihtiyacı gelir.\",\"image\":\"assets/images/blog-4.jpg\",\"image_alt\":\"İşçi arıların ortasında kraliçe arı\",\"embed_keys\":[],\"body\":[\"Bal akışı, kovana boş petek ve güçlü bir yavru düzeni kaldığında başlar. Kraliçe düzgün yumurtlamıyorsa tarlacı arı da bir süre sonra azalır. Hasadı büyütmeden önce bu dengeye bakılır.\",\"Boş göz kalmadığında arı balı yavru alanına taşır ya da oğul hazırlığına döner. Zamanında eklenen bir kat, koloniyi sıkıştırmadan akışı uzatır.\",\"Hasat, kovanın kış payı ayrıldıktan sonra yapılır. Akışın tamamını almak o yılın kavanozunu doldurur, sonraki baharın kolonisini ise zayıflatır.\"],\"author\":\"Tuana Arıcılık\",\"time\":\"16:20\",\"category\":\"Üretim\",\"category_key\":\"uretim\",\"tags\":[\"Koloni\",\"Hasat\",\"Petek\"],\"figure\":{\"image\":\"assets/images/service-production.jpg\",\"image_alt\":\"Bal dolu çerçeveyi tutan arıcı\",\"caption\":\"Hasat, kovanın kış payı ayrıldıktan sonra yapılır.\"}}','2026-10-10 10:53:20');
/*!40000 ALTER TABLE `blocks` ENABLE KEYS */;
