INSERT INTO `sections` VALUES (1,'home','hero','hero','Karşılama',10,1,'{\"anchor\":\"anasayfa\",\"title_lines\":[\"Saf Balın\",\"Sonsuz\",\"Sevgisi\"],\"text\":\"Kendi kovanlarımızdan, katkısız ve mevsimin ritmine sadık üretilen bal. Tuana Arıcılık her kavanoza yılların emeğini ve arının özenini koyar.\",\"image\":\"assets/images/about.jpg\",\"image_alt\":\"Kavanozda süzme bal ve tahta bal kaşığı\",\"primary_button\":{\"label\":\"Daha Fazla\",\"url\":\"#hakkimizda\"},\"secondary_button\":{\"label\":\"Tanıtımı İzle\",\"url\":\"#tanitim\",\"modal\":\"intro\",\"icon\":\"play\"},\"motion\":{\"stagger\":0,\"distance\":42,\"duration\":900,\"once\":true,\"slots\":{\"copy\":\"from-left\",\"media\":\"from-right\"}}}','2026-10-10 10:24:57'),(2,'home','features','features','Öne çıkanlar',20,1,'{\"anchor\":\"one-cikanlar\",\"motion\":{\"stagger\":170,\"distance\":64,\"duration\":800,\"once\":true,\"slots\":{\"items\":\"rise\"}},\"block_keys\":[\"arici-bali\",\"ari-bahcesi\",\"ari-urunleri\"]}','2026-10-10 10:46:35'),(3,'home','about','about','Hakkımızda',30,1,'{\"anchor\":\"hakkimizda\",\"badge_value\":\"24+\",\"badge_label\":\"Yıllık deneyim\",\"eyebrow\":\"Hakkımızda\",\"title_lines\":[\"Size en iyi bal\",\"deneyimini sunuyoruz\"],\"text\":\"Arıları acele ettirmeden, peteği zorlamadan ve balı yüksek ısıya maruz bırakmadan çalışıyoruz. Tuana Arıcılık, aileden gelen bilgiyi düzenli kovan takibiyle birleştirir.\",\"text_extra\":\"Her hasat ayrı kaydedilir. Çiçek kaynağı, kovan ve süzüm tarihi belli olan balı, kısa yoldan ve açık bilgiyle ulaştırmayı önemseriz.\",\"image\":\"assets/images/pledge.jpg\",\"image_alt\":\"Petekten damlayan taze bal\",\"button\":{\"label\":\"Keşfet\",\"url\":\"#hizmetler\"},\"motion\":{\"stagger\":0,\"distance\":80,\"duration\":900,\"once\":true,\"slots\":{\"media\":\"from-left\",\"copy\":\"from-right\"}}}','2026-10-10 10:24:57'),(4,'home','banner','banner','Vurgu bandı',40,1,'{\"anchor\":\"dogal-bal\",\"eyebrow\":\"Doğal bal\",\"title_lines\":[\"Şimdiye kadar üretilmiş\",\"en iyi balı deneyimleyin\"],\"text\":\"Altın rengi, yoğun kıvamı ve çiçekten gelen karakteriyle Tuana balı; kahvaltıdan mutfağa kadar aynı saflıkta kalır.\",\"image\":\"assets/images/blog-1.jpg\",\"image_alt\":\"Işık alan altın rengi petek\",\"button\":{\"label\":\"Keşfet\",\"url\":\"#urunler\"},\"motion\":{\"stagger\":0,\"distance\":36,\"duration\":900,\"once\":true,\"slots\":{\"media\":\"zoom\",\"copy\":\"rise\"}}}','2026-10-10 10:24:57'),(5,'home','services','services','Hizmetler',50,1,'{\"anchor\":\"hizmetler\",\"eyebrow\":\"Hizmetlerimiz\",\"title_lines\":[\"İyi bal yapmayız.\",\"En iyi balı üretiriz.\"],\"text\":\"Kovan bakımından hasada, oğul toplamadan süzüme kadar arıcılığın emek isteyen işlerini kendi standartlarımızla yürütürüz.\",\"items\":[{\"title\":\"Arıcılık\",\"text\":\"Kovanları mevsim boyunca izler, koloniyi strese sokmadan güçlü ve dengeli tutarız.\",\"image\":\"assets/images/service-keeping.jpg\",\"image_alt\":\"Arıcı kovan başında çerçeve kontrol ediyor\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"#iletisim\"}},{\"title\":\"Bal İşleme\",\"text\":\"Balı dinlendirir, süzülür ve kavanoza alınırken ısıl işlem uygulamadan karakterini koruruz.\",\"image\":\"assets/images/promo.jpg\",\"image_alt\":\"Çerçeveden kaba süzülen bal\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"#iletisim\"}},{\"title\":\"Oğul Toplama\",\"text\":\"Oğul veren koloniyi güvenli şekilde toplar, yeni kovana yerleştirir ve kaybı önleriz.\",\"image\":\"assets/images/service-swarm.jpg\",\"image_alt\":\"Çerçeve çevresinde uçuşan bal arıları\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"#iletisim\"}},{\"title\":\"Bal Üretimi\",\"text\":\"Olgunlaşmış peteği zamanında alır, verimi koloninin ihtiyacını gözeterek planlarız.\",\"image\":\"assets/images/service-production.jpg\",\"image_alt\":\"Bal dolu çerçeveyi tutan arıcı\",\"button\":{\"label\":\"Daha Fazla\",\"url\":\"#iletisim\"}}],\"motion\":{\"stagger\":140,\"distance\":48,\"duration\":780,\"once\":true,\"slots\":{\"head\":\"rise\",\"items\":\"rise\"}}}','2026-10-10 10:24:57'),(6,'home','products','products','Ürünler',60,1,'{\"anchor\":\"urunler\",\"pledge_title\":[\"%100\",\"memnuniyet\",\"sözü veriyoruz\"],\"pledge_text\":\"Beğenmediğiniz kavanozu bize bildirmeniz yeterli. Ürünün hikâyesini açıkça anlatırız.\",\"pledge_image\":\"assets/images/pledge.jpg\",\"pledge_alt\":\"Elde tutulan petekten akan bal\",\"pledge_button\":{\"label\":\"Daha Fazla\",\"url\":\"#iletisim\"},\"eyebrow\":\"Ürünümüz\",\"title_lines\":[\"Piyasadaki en tatlı bal\"],\"text\":\"Kovandan çıkan üç temel ürün. Kısa liste, net içerik, izlenebilir üretim.\",\"items\":[{\"title\":\"Arı Poleni\",\"image\":\"assets/images/blog-1.jpg\",\"image_alt\":\"Altın rengi petek dokusu\",\"points\":[\"Çiçek kaynağı belli\",\"Katkı eklenmez\",\"Serin ve kuru saklanır\"]},{\"title\":\"Bal Sabunu\",\"image\":\"assets/images/beeswax.jpg\",\"image_alt\":\"Doğal sarı bal mumu bloğu\",\"points\":[\"Kovan peteğinden\",\"Doğal sarı renk\",\"Mum ve bakım için\"]},{\"title\":\"Arı Sütü\",\"image\":\"assets/images/blog-4.jpg\",\"image_alt\":\"Kraliçe arı ve işçi arılar\",\"points\":[\"Taze toplanır\",\"Soğukta korunur\",\"Kısa sürede teslim\"]}],\"motion\":{\"stagger\":130,\"distance\":64,\"duration\":820,\"once\":true,\"slots\":{\"pledge\":\"from-left\",\"intro\":\"from-right\",\"items\":\"rise\"}}}','2026-10-10 10:24:57'),(7,'home','why','why','Neden biz',70,1,'{\"anchor\":\"neden-biz\",\"eyebrow\":\"Neden biz\",\"title_lines\":[\"Bulabileceğiniz en lezzetli\",\"ve doğal bal\"],\"text\":\"Gösterişli vaat yerine, kovanın başında duran bir üretim tercih ediyoruz.\",\"image\":\"assets/images/why.jpg\",\"image_alt\":\"Arıcı bal dolu çerçeveyi tutuyor\",\"items\":[{\"title\":\"%100 doğal\",\"text\":\"Bala şeker, şurup ya da aroma katmayız. Kıvamı mevsim belirler.\"},{\"title\":\"Özenli işleme\",\"text\":\"Süzüm ve dinlendirme düşük ısıda, peteğin karakteri bozulmadan yapılır.\"},{\"title\":\"Özenli teslimat\",\"text\":\"Kavanozlar sızdırmayacak şekilde paketlenir ve kısa sürede yola çıkar.\"},{\"title\":\"Yüksek standart\",\"text\":\"Her parti ayrı not edilir. Kaynağını sorduğunuzda net cevap alırsınız.\"}],\"motion\":{\"stagger\":110,\"distance\":52,\"duration\":800,\"once\":true,\"slots\":{\"photo\":\"zoom\",\"card\":\"from-left\",\"items\":\"rise\"}}}','2026-10-10 10:24:57'),(8,'home','benefits','benefits','Balın profili',80,1,'{\"anchor\":\"faydalar\",\"eyebrow\":\"Balın profili\",\"title_lines\":[\"Organik ve size\",\"iyi gelen bal\"],\"text\":\"Bu çubuklar bir tedavi vaadi değildir. Doğal balın tanıtımında sık anlatılan genel bileşim profilini gösterir.\",\"image\":\"assets/images/about.jpg\",\"image_alt\":\"Bal kavanozu ve bal kaşığı\",\"bars\":[{\"label\":\"Antioksidan\",\"value\":90},{\"label\":\"Antibakteriyel etki\",\"value\":60},{\"label\":\"Enerji\",\"value\":70},{\"label\":\"Antienflamatuvar\",\"value\":85},{\"label\":\"Doğal şeker\",\"value\":75}],\"motion\":{\"stagger\":90,\"distance\":56,\"duration\":800,\"once\":true,\"slots\":{\"copy\":\"from-left\",\"photo\":\"zoom\",\"bars\":\"from-right\"}}}','2026-10-10 10:24:57'),(9,'home','promo','promo','Promosyon',90,1,'{\"anchor\":\"promosyon\",\"eyebrow\":\"Promosyon\",\"title_lines\":[\"İlk alışverişe bu ay\",\"%30’a varan indirim\"],\"text\":\"İlk siparişinizi bu ay içinde verdiğinizde seçili kavanozlarda dönemsel indirim uygulanır.\",\"image\":\"assets/images/promo.jpg\",\"image_alt\":\"Petekten kaba damlayan bal\",\"button\":{\"label\":\"Promosyonu Al\",\"url\":\"#iletisim\"},\"motion\":{\"stagger\":0,\"distance\":36,\"duration\":860,\"once\":true,\"slots\":{\"photo\":\"zoom\",\"copy\":\"rise\"}}}','2026-10-10 10:24:57'),(10,'home','testimonials','testimonials','Yorumlar',100,1,'{\"anchor\":\"yorumlar\",\"eyebrow\":\"Müşteri yorumları\",\"title_lines\":[\"Müşterilerimizin görüşleri\"],\"text\":\"Soframıza giren balı anlatan kısa notlar. İsimler örnek yorumlar içindir.\",\"items\":[{\"quote\":\"Kahvaltılık balın kıvamı ve kokusu market raflarındakine benzemiyor. Çiçek kaynağını sorduğumda net cevap aldım.\",\"name\":\"Ayşe Yılmaz\",\"role\":\"Çiftçi\",\"initials\":\"AY\",\"tone\":1},{\"quote\":\"Pastacılıkta ölçüsü şaşmayan, yanık tat bırakmayan bir bal. Kavanoz bitince aynı partiden devam edebildim.\",\"name\":\"Emre Demir\",\"role\":\"Aşçı\",\"initials\":\"ED\",\"tone\":2},{\"quote\":\"Ambalaj sağlam geldi, etiket sade ve okunaklı. Çocukların ekmeğine sürdüğümüz günlük bal bu oldu.\",\"name\":\"Selin Kaya\",\"role\":\"Öğretmen\",\"initials\":\"SK\",\"tone\":3},{\"quote\":\"Oğul toplama işinde acele etmeden, koloniyi yerinde anlattılar. Sonrasında bal siparişi de buradan gidiyor.\",\"name\":\"Burak Acar\",\"role\":\"Esnaf\",\"initials\":\"BA\",\"tone\":4}],\"motion\":{\"stagger\":120,\"distance\":36,\"duration\":740,\"once\":true,\"slots\":{\"head\":\"rise\",\"items\":\"rise\"}}}','2026-10-10 10:24:57'),(11,'home','blog','blog','Blog',110,1,'{\"anchor\":\"blog\",\"eyebrow\":\"Blogumuz\",\"title\":\"Son haberler ve yazılar\",\"button\":{\"label\":\"Tüm Yazılar\",\"url\":\"/blog\"},\"motion\":{\"stagger\":140,\"distance\":48,\"duration\":780,\"once\":true,\"slots\":{\"head\":\"rise\",\"media\":\"from-left\",\"body\":\"from-right\"}},\"source\":\"posts\",\"limit\":4}','2026-10-10 10:46:35'),(12,'hakkimizda','ust','pagehead','Sayfa bandı',10,1,'{\"anchor\":\"ust\",\"title\":\"Hakkımızda\",\"description\":\"Tuana Arıcılık, aileden gelen bilgiyi düzenli kovan takibiyle birleştirir.\",\"image\":\"assets/images/about.jpg\",\"image_alt\":\"Kavanozda süzme bal ve tahta bal kaşığı\",\"crumbs\":[{\"label\":\"Ana Sayfa\",\"url\":\"/\"},{\"label\":\"Hakkımızda\",\"url\":\"\"}],\"motion\":{\"stagger\":0,\"distance\":28,\"duration\":760,\"once\":true,\"slots\":{\"copy\":\"rise\"}}}','2026-10-10 10:46:35'),(13,'hakkimizda','about','about','Hakkımızda',20,1,'{\"anchor\":\"hikaye\",\"motion\":{\"stagger\":0,\"distance\":72,\"duration\":880,\"once\":true,\"slots\":{\"media\":\"from-left\",\"copy\":\"from-right\"}},\"badge_value\":\"24+\",\"badge_label\":\"Yıllık deneyim\",\"eyebrow\":\"Hakkımızda\",\"title_lines\":[\"Size en iyi bal\",\"deneyimini sunuyoruz\"],\"text\":\"Arıları acele ettirmeden, peteği zorlamadan ve balı yüksek ısıya maruz bırakmadan çalışıyoruz. Tuana Arıcılık, aileden gelen bilgiyi düzenli kovan takibiyle birleştirir.\",\"text_extra\":\"Her hasat ayrı kaydedilir. Çiçek kaynağı, kovan ve süzüm tarihi belli olan balı, kısa yoldan ve açık bilgiyle ulaştırmayı önemseriz.\",\"image\":\"assets/images/pledge.jpg\",\"image_alt\":\"Petekten damlayan taze bal\",\"button\":{\"label\":\"Keşfet\",\"url\":\"/#hizmetler\"}}','2026-10-10 10:46:35'),(14,'hakkimizda','kartlar','features','Kartlar',30,1,'{\"anchor\":\"kartlar\",\"block_keys\":[\"arici-bali\",\"ari-bahcesi\",\"ari-urunleri\"],\"motion\":{\"stagger\":160,\"distance\":56,\"duration\":780,\"once\":true,\"slots\":{\"items\":\"rise\"}}}','2026-10-10 10:46:35'),(15,'blog','ust','pagehead','Sayfa bandı',10,1,'{\"anchor\":\"ust\",\"title\":\"Blog\",\"description\":\"Kovandan sofraya uzanan arıcılık notları.\",\"image\":\"assets/images/banner.jpg\",\"image_alt\":\"Petek üzerindeki bal arıları\",\"crumbs\":[{\"label\":\"Ana Sayfa\",\"url\":\"/\"},{\"label\":\"Blog\",\"url\":\"\"}],\"motion\":{\"stagger\":0,\"distance\":28,\"duration\":760,\"once\":true,\"slots\":{\"copy\":\"rise\"}}}','2026-10-10 10:46:35'),(16,'blog','yazilar','blog','Yazılar',20,1,'{\"anchor\":\"yazilar\",\"source\":\"posts\",\"motion\":{\"stagger\":120,\"distance\":46,\"duration\":780,\"once\":true,\"slots\":{\"media\":\"from-left\",\"body\":\"from-right\"}}}','2026-10-10 10:46:35');
